// Development reference only; never shipped as part of d2-rs.
//
// Route validation oracle for recipe `tala-route-validation`
// (tools/fixtures/tala-oracle.toml): reads the request list generated by
// scripts/tala_oracle_fixtures.py on stdin and writes, per request, the
// public d2talalayout.RouteEdges / Layout error text and the routed graph.
package main

import (
 "context"
 "encoding/json"
 "os"
 "strconv"
 "github.com/d2lang/d2/d2graph"
 "github.com/d2lang/d2/d2layouts/d2talalayout"
 "github.com/d2lang/d2/lib/geo"
)

type route struct { Points [][]string `json:"points"`; Count int `json:"count"`; Tail []string `json:"tail"` }
type input struct { Name string `json:"name"`; Routes []route `json:"routes"`; Requested []int `json:"requested"`; Cancel bool `json:"cancel"`; Layout bool `json:"layout"`; Arrowhead string `json:"arrowhead"`; MissingPosition bool `json:"missing_position"` }
func number(s string) float64 { v,err:=strconv.ParseFloat(s,64);if err!=nil{panic(err)};return v }
func points(spec route) []*geo.Point {
 result:=[]*geo.Point{}
 if spec.Count>0 { for i:=0;i<spec.Count;i++ {result=append(result,geo.NewPoint(110+float64(i%2)*140,50))} }
 for _,p:=range spec.Points {result=append(result,geo.NewPoint(number(p[0]),number(p[1])))}
 if spec.Tail!=nil {result[len(result)-1]=geo.NewPoint(number(spec.Tail[0]),number(spec.Tail[1]))}
 return result
}
func main() {
 var inputs []input
 if err:=json.NewDecoder(os.Stdin).Decode(&inputs);err!=nil{panic(err)}
 rows:=[]any{}
 for _,item:=range inputs {
  g:=d2graph.NewGraph()
  for i,id:=range []string{"a","b"} {
   obj:=&d2graph.Object{Graph:g,Parent:g.Root,ID:id,IDVal:id,Box:geo.NewBox(geo.NewPoint(10+float64(i)*240,20),100,60),Children:make(map[string]*d2graph.Object)}
   g.Objects=append(g.Objects,obj);g.Root.Children[id]=obj;g.Root.ChildrenArray=append(g.Root.ChildrenArray,obj)
  }
  if item.MissingPosition {g.Objects[0].TopLeft=nil}
  for index,spec:=range item.Routes {g.Edges=append(g.Edges,&d2graph.Edge{Src:g.Objects[0],Dst:g.Objects[1],Index:index,DstArrow:true,Route:points(spec)})}
  if item.Arrowhead!="" {g.Edges[0].SrcArrowhead=&d2graph.Attributes{};g.Edges[0].SrcArrowhead.Shape.Value=item.Arrowhead}
  selected:=[]*d2graph.Edge{}
  for _,i:=range item.Requested {selected=append(selected,g.Edges[i])}
  ctx,cancel:=context.WithCancel(context.Background());if item.Cancel{cancel()}
  var err error
  if item.Layout {err=d2talalayout.Layout(ctx,g,&d2talalayout.Options{Seeds:[]int64{1},MaxConcurrency:1})} else {err=d2talalayout.RouteEdges(ctx,g,selected)}
  cancel()
  message:="";if err!=nil{message=err.Error()}
  row:=map[string]any{"input":item,"error":message}
  if err==nil {row["graph"]=g}
  rows=append(rows,row)
 }
 enc:=json.NewEncoder(os.Stdout);enc.SetIndent("","  ");if err:=enc.Encode(rows);err!=nil{panic(err)}
}
